def agent_main(problem_data: dict) -> list[dict]:
    episode = Episode(problem_data if isinstance(problem_data, dict) else {})
    try:
        return episode.run()
    except Exception as exc:  # never end on an error: use what is left of the step budget to close out
        episode.note('[error] %s: %s' % (type(exc).__name__, exc))
        try:
            if not episode.finished and episode.steps_left() > 0:
                episode.finish(final=True)
        except Exception as exc2:
            episode.note('[error] %s: %s' % (type(exc2).__name__, exc2))
        return [dict(kind='note', text=t) for t in episode.ledger] + [episode.spend_note()]
